insert into public.packages (slug,title,short_description,full_description,featured_image,gallery,nights,dives,experience_level,audiences,accommodation_included,meals_included,transfers_included,whale_shark,manta,base_price,currency,featured,highlights,accommodation_info,equipment_info,transfer_info,important_notes,cancellation_policy,sort_order) select x->>'slug',x->>'title',x->>'shortDescription',x->>'fullDescription',x->>'featuredImage',array(select jsonb_array_elements_text(x->'gallery')),(x->>'nights')::int,(x->>'dives')::int,x->>'experienceLevel',array(select jsonb_array_elements_text(x->'audiences')),(x->>'accommodationIncluded')::boolean,(x->>'mealsIncluded')::boolean,(x->>'transfersIncluded')::boolean,(x->>'whaleShark')::boolean,(x->>'manta')::boolean,(x->>'basePrice')::numeric,x->>'currency',(x->>'featured')::boolean,array(select jsonb_array_elements_text(x->'highlights')),x->>'accommodationInfo',x->>'equipmentInfo',x->>'transferInfo',array(select jsonb_array_elements_text(x->'importantNotes')),x->>'cancellationPolicy',coalesce((x->>'_sort')::int, 0) from jsonb_array_elements('[{"id":"pkg-discover-dhangethi","slug":"discover-dhangethi","title":"Discover Dhangethi","shortDescription":"A gentle first taste of island life and the South Ari reefs — perfect for newcomers to the Maldives.","fullDescription":"Discover Dhangethi is our warm welcome to the Maldives. Settle into the rhythm of a local island, meet the ocean at your own pace, and let our team introduce you to the reefs on our doorstep. Whether you are trying diving for the first time or easing back into the water, this stay balances underwater time with slow island days.","featuredImage":"/images/pkg-discover.png","gallery":["/images/pkg-discover.png","/images/reef-dive.png","/images/dhangethi-aerial.png","/images/dhangethi-aerial.png"],"nights":4,"dives":4,"experienceLevel":"Beginner","audiences":["Beginner","Solo Traveller","Couple","Diving and Stay"],"accommodationIncluded":true,"mealsIncluded":true,"transfersIncluded":true,"whaleShark":false,"manta":false,"basePrice":690,"currency":"USD","featured":true,"highlights":["Guided house-reef and nearby reef dives","Relaxed pace ideal for new and returning divers","Authentic local-island guesthouse stay","Time to explore Dhangethi beyond the water"],"inclusions":[{"label":"4 nights local-island accommodation","type":"included"},{"label":"Daily breakfast","type":"included"},{"label":"4 guided dives with tanks and weights","type":"included"},{"label":"Speedboat / ferry transfer coordination","type":"included"},{"label":"Flights to the Maldives","type":"excluded"},{"label":"Full dive equipment rental","type":"excluded"},{"label":"Lunch and dinner","type":"excluded"}],"itinerary":[{"day":1,"title":"Arrival & island welcome","description":"Arrive on Dhangethi, settle in, and join a relaxed orientation with the team."},{"day":2,"title":"First dives","description":"Two guided dives on gentle nearby reefs, followed by a slow island afternoon."},{"day":3,"title":"Reef exploration","description":"Two more dives exploring the colour and life of South Ari reefs."},{"day":4,"title":"Island day","description":"A free day for the beach, the harbour and local cafés before departure prep."}],"accommodationInfo":"Comfortable local guesthouse rooms on Dhangethi. Final room categories and options will be confirmed with the client.","equipmentInfo":"Tanks and weights are included. Full equipment rental (BCD, regulator, wetsuit, mask, fins, computer) can be arranged for an additional placeholder fee.","transferInfo":"Dhangethi is reached by speedboat or the atoll ferry from Malé. We help coordinate the most suitable transfer for your arrival.","importantNotes":["Certified divers should bring their certification card and logbook.","A medical self-declaration may be required before diving."],"cancellationPolicy":"Cancellation policy to be confirmed by the client. This is a placeholder."},{"id":"pkg-south-ari-explorer","slug":"south-ari-explorer","title":"South Ari Explorer","shortDescription":"A dive-focused week across the channels, thilas and reefs that make South Ari Atoll world famous.","fullDescription":"South Ari Explorer is built for divers who want to see it all. Across the week we range further from the island to dive dramatic channels, coral thilas and vibrant reefs, chasing the marine life South Ari is known for. Evenings return you to the calm of Dhangethi and the warmth of local hospitality.","featuredImage":"/images/pkg-explorer.png","gallery":["/images/pkg-explorer.png","/images/site-channel.png","/images/site-thila.png","/images/reef-dive.png"],"nights":7,"dives":12,"experienceLevel":"Certified Diver","audiences":["Certified Diver","Solo Traveller","Group","Diving and Stay"],"accommodationIncluded":true,"mealsIncluded":true,"transfersIncluded":true,"whaleShark":true,"manta":true,"basePrice":1490,"currency":"USD","featured":true,"highlights":["12 dives across channels, thilas and reefs","Chances for whale shark and manta encounters","Small guided groups with local knowledge","A full week of island living"],"inclusions":[{"label":"7 nights local-island accommodation","type":"included"},{"label":"Daily breakfast","type":"included"},{"label":"12 guided dives with tanks and weights","type":"included"},{"label":"Whale shark and manta excursions (sightings never guaranteed)","type":"included"},{"label":"Flights to the Maldives","type":"excluded"},{"label":"Full dive equipment rental","type":"excluded"},{"label":"Nitrox (available on request)","type":"excluded"}],"itinerary":[{"day":1,"title":"Arrival","description":"Arrive, settle in and check gear with the team."},{"day":2,"title":"Warm-up dives","description":"Two check dives to find your rhythm on nearby reefs."},{"day":3,"title":"Channels","description":"Drift the channels in search of sharks, rays and pelagic action."},{"day":4,"title":"Whale shark search","description":"A dedicated excursion into the South Ari whale shark zone."},{"day":5,"title":"Thilas","description":"Explore coral pinnacles teeming with reef life."},{"day":6,"title":"Manta & reefs","description":"Visit cleaning stations and colourful reef gardens."},{"day":7,"title":"Island day","description":"A relaxed final day on Dhangethi before departure."}],"accommodationInfo":"Comfortable local guesthouse rooms on Dhangethi across seven nights. Room options confirmed with the client.","equipmentInfo":"Tanks and weights included. Full equipment rental and Nitrox available for a placeholder fee.","transferInfo":"Speedboat or ferry transfers from Malé are coordinated to suit your flight times.","importantNotes":["Suitable for certified divers; recent dive experience recommended.","Please share your certification level and logged dives when enquiring."],"cancellationPolicy":"Cancellation policy to be confirmed by the client. This is a placeholder."},{"id":"pkg-whale-shark-week","slug":"whale-shark-week","title":"Whale Shark Week","shortDescription":"Maximise your chances of swimming beside the ocean’s gentle giants in their South Ari home.","fullDescription":"South Ari Atoll is one of the few places on earth where whale sharks are seen year round. Whale Shark Week is designed around them — with dedicated excursions, flexible timing and expert local guides who know where to look. Between encounters, dive the reefs and soak up island life.","featuredImage":"/images/whale-shark.png","gallery":["/images/whale-shark.png","/images/whale-shark.png","/images/manta.png","/images/pkg-escape.png"],"nights":6,"dives":8,"experienceLevel":"All Levels","audiences":["Beginner","Certified Diver","Couple","Group","Diving and Stay"],"accommodationIncluded":true,"mealsIncluded":true,"transfersIncluded":true,"whaleShark":true,"manta":true,"basePrice":1290,"currency":"USD","featured":true,"highlights":["Multiple dedicated whale shark excursions","Snorkel and dive options for all levels","Manta cleaning station visits","Local guides who know the season and the sites"],"inclusions":[{"label":"6 nights local-island accommodation","type":"included"},{"label":"Daily breakfast","type":"included"},{"label":"8 guided dives with tanks and weights","type":"included"},{"label":"Multiple whale shark excursions (sightings never guaranteed)","type":"included"},{"label":"Flights to the Maldives","type":"excluded"},{"label":"Full dive equipment rental","type":"excluded"}],"itinerary":[{"day":1,"title":"Arrival","description":"Arrive on Dhangethi and settle in."},{"day":2,"title":"Whale shark excursion","description":"First dedicated trip into the whale shark zone."},{"day":3,"title":"Reef dives","description":"Explore nearby reefs and marine life."},{"day":4,"title":"Whale shark & manta","description":"A combined excursion for the big encounters."},{"day":5,"title":"Island & optional dive","description":"Relax on the island with an optional dive."},{"day":6,"title":"Final search","description":"One more chance with the gentle giants before departure."}],"accommodationInfo":"Local guesthouse rooms on Dhangethi. Options confirmed with the client.","equipmentInfo":"Tanks and weights included. Snorkel and full dive rental available (placeholder fee).","transferInfo":"Speedboat or ferry transfers coordinated from Malé.","importantNotes":["Whale shark and manta sightings are wild and can never be guaranteed.","Non-divers and snorkellers are welcome on excursions."],"cancellationPolicy":"Cancellation policy to be confirmed by the client. This is a placeholder."},{"id":"pkg-dive-island-escape","slug":"dive-and-island-escape","title":"Dive and Island Escape","shortDescription":"A romantic blend of easy diving and slow island days — made for couples and those who want balance.","fullDescription":"Not every trip is about logging maximum dives. Dive and Island Escape pairs a handful of memorable dives with the space to simply be — sunset walks, quiet beaches, local food and the unhurried charm of Dhangethi. Ideal for couples, and for divers travelling with a non-diving partner.","featuredImage":"/images/pkg-escape.png","gallery":["/images/pkg-escape.png","/images/dhangethi-aerial.png","/images/pkg-escape.png","/images/reef-dive.png"],"nights":5,"dives":4,"experienceLevel":"All Levels","audiences":["Couple","Beginner","Diving and Stay","Solo Traveller"],"accommodationIncluded":true,"mealsIncluded":true,"transfersIncluded":true,"whaleShark":false,"manta":true,"basePrice":890,"currency":"USD","featured":true,"highlights":["A relaxed balance of diving and island time","Perfect for couples and mixed diver / non-diver travel","Optional snorkelling and excursions","Sunset harbour evenings"],"inclusions":[{"label":"5 nights local-island accommodation","type":"included"},{"label":"Daily breakfast","type":"included"},{"label":"4 guided dives with tanks and weights","type":"included"},{"label":"Transfer coordination","type":"included"},{"label":"Flights to the Maldives","type":"excluded"},{"label":"Full dive equipment rental","type":"excluded"}],"itinerary":[{"day":1,"title":"Arrival","description":"Arrive and unwind into island time."},{"day":2,"title":"Easy dives","description":"Two gentle dives, then a free afternoon."},{"day":3,"title":"Island & optional excursion","description":"Beach, café and an optional snorkelling trip."},{"day":4,"title":"Reef day","description":"Two more dives on the reefs you love most."},{"day":5,"title":"Slow morning","description":"A relaxed final morning before departure."}],"accommodationInfo":"Comfortable local guesthouse rooms, couple-friendly options confirmed with the client.","equipmentInfo":"Tanks and weights included. Full rental available for a placeholder fee.","transferInfo":"Speedboat or ferry transfers coordinated from Malé.","importantNotes":["Great for divers travelling with a non-diving partner.","Let us know your interests so we can tailor the balance."],"cancellationPolicy":"Cancellation policy to be confirmed by the client. This is a placeholder."}]'::jsonb) x on conflict (slug) do update set title=excluded.title,short_description=excluded.short_description,full_description=excluded.full_description,featured_image=excluded.featured_image,gallery=excluded.gallery,nights=excluded.nights,dives=excluded.dives,experience_level=excluded.experience_level,audiences=excluded.audiences,accommodation_included=excluded.accommodation_included,meals_included=excluded.meals_included,transfers_included=excluded.transfers_included,whale_shark=excluded.whale_shark,manta=excluded.manta,base_price=excluded.base_price,currency=excluded.currency,featured=excluded.featured,highlights=excluded.highlights,accommodation_info=excluded.accommodation_info,equipment_info=excluded.equipment_info,transfer_info=excluded.transfer_info,important_notes=excluded.important_notes,cancellation_policy=excluded.cancellation_policy,sort_order=excluded.sort_order;
