insert into public.courses (slug,title,category,description,long_description,duration,minimum_age,required_certification,number_of_dives,price,currency,featured_image,highlights,what_you_learn,featured,sort_order) select x->>'slug',x->>'title',x->>'category',x->>'description',x->>'longDescription',x->>'duration',x->>'minimumAge',x->>'requiredCertification',(x->>'numberOfDives')::int,(x->>'price')::numeric,x->>'currency',x->>'featuredImage',array(select jsonb_array_elements_text(x->'highlights')),array(select jsonb_array_elements_text(x->'whatYouLearn')),(x->>'featured')::boolean,(x->>'_sort')::int from jsonb_array_elements('[{"id":"course-discover-scuba","slug":"discover-scuba-diving","title":"Discover Scuba Diving","category":"First-Time Diving","description":"Your first underwater breath, guided every moment by a professional. No certification needed.","longDescription":"Discover Scuba Diving is the gentlest possible introduction to the underwater world. After a short briefing on the basics, you will take your first breaths in shallow, calm water alongside an instructor, then explore a gentle reef. No experience or certification is required — just curiosity.","duration":"Half day","minimumAge":"Minimum age to be confirmed","requiredCertification":"None","numberOfDives":1,"price":120,"currency":"USD","featuredImage":"/images/learn-to-dive.png","featured":true,"highlights":["No experience required","One-to-one attention","Shallow, calm water start"],"whatYouLearn":["Basic scuba equipment and how it works","Simple breathing and comfort underwater","A guided shallow dive on a gentle reef"],"_sort":0},{"id":"course-open-water","slug":"open-water-diver","title":"Open Water Diver","category":"Beginner Certification","description":"Become a certified diver, free to explore the world’s oceans to recreational limits.","longDescription":"The Open Water Diver course is your passport to diving worldwide. Over several days you will build knowledge, master core skills in confined water, and complete open-water training dives on the reefs of South Ari Atoll. Finish as a certified diver, ready to dive with a buddy.","duration":"3–4 days","minimumAge":"Minimum age to be confirmed","requiredCertification":"None","numberOfDives":4,"price":590,"currency":"USD","featuredImage":"/images/reef-dive.png","featured":true,"highlights":["Full entry-level certification","Reef training dives","Lifetime qualification"],"whatYouLearn":["Dive theory and planning fundamentals","Core skills in confined water","Four open-water training dives","Buddy diving and safety procedures"],"_sort":1},{"id":"course-advanced","slug":"advanced-diver","title":"Advanced Diver","category":"Advanced Courses","description":"Extend your range and confidence with deeper dives, drift diving and navigation.","longDescription":"Build on your certification with adventure dives that expand what you can do. Explore deeper reefs, master underwater navigation, and experience the drift diving South Ari is famous for — all under the guidance of experienced local instructors.","duration":"2–3 days","minimumAge":"Minimum age to be confirmed","requiredCertification":"Open Water Diver (or equivalent)","numberOfDives":5,"price":490,"currency":"USD","featuredImage":"/images/pkg-explorer.png","featured":true,"highlights":["Deep and drift dives","Underwater navigation","Greater independence"],"whatYouLearn":["Deeper diving within recreational limits","Underwater navigation","Drift and current techniques","A choice of adventure specialities"],"_sort":2},{"id":"course-rescue","slug":"rescue-diver","title":"Rescue Diver","category":"Rescue and Safety","description":"Learn to prevent and manage problems — the most rewarding course many divers take.","longDescription":"The Rescue Diver course transforms how you dive. You will learn to anticipate, recognise and respond to dive emergencies, building confidence and awareness that makes you a safer, calmer diver and a better buddy.","duration":"3–4 days","minimumAge":"Minimum age to be confirmed","requiredCertification":"Advanced Diver + first aid (to be confirmed)","numberOfDives":4,"price":550,"currency":"USD","featuredImage":"/images/dive-briefing.png","featured":false,"highlights":["Emergency management","Self-rescue skills","Confidence and awareness"],"whatYouLearn":["Recognising and preventing dive problems","Self-rescue and buddy assistance","Managing emergencies calmly","Search and recovery basics"],"_sort":3},{"id":"course-nitrox","slug":"enriched-air-nitrox","title":"Enriched Air (Nitrox)","category":"Speciality Courses","description":"Extend your no-decompression time and dive longer with enriched air.","longDescription":"Diving with enriched air (Nitrox) can extend your bottom time and shorten surface intervals. This speciality teaches you how to analyse, plan and dive with enriched air safely — ideal for divers doing multiple dives a day.","duration":"1 day","minimumAge":"Minimum age to be confirmed","requiredCertification":"Open Water Diver (or equivalent)","numberOfDives":2,"price":220,"currency":"USD","featuredImage":"/images/site-thila.png","featured":false,"highlights":["Longer bottom times","Great for dive-heavy trips","Quick to complete"],"whatYouLearn":["How enriched air works","Analysing and marking cylinders","Planning enriched air dives"],"_sort":4},{"id":"course-divemaster","slug":"divemaster","title":"Divemaster","category":"Professional Development","description":"Take your first step into a professional diving career in the Maldives.","longDescription":"The Divemaster programme is the first professional level in recreational diving. Work alongside our team, refine your skills, deepen your dive theory and learn to guide and support divers. A rewarding path for those who want to make the ocean their workplace.","duration":"Several weeks (flexible)","minimumAge":"Minimum age to be confirmed","requiredCertification":"Rescue Diver + logged dives (to be confirmed)","numberOfDives":20,"price":1200,"currency":"USD","featuredImage":"/images/island-dhoni.png","featured":false,"highlights":["First professional rating","Real experience with our team","Guiding skills"],"whatYouLearn":["Advanced dive theory","Guiding and supervising divers","Dive site and risk management","Professional standards and conduct"],"_sort":5}]'::jsonb) x on conflict (slug) do update set title=excluded.title,category=excluded.category,description=excluded.description,long_description=excluded.long_description,duration=excluded.duration,minimum_age=excluded.minimum_age,required_certification=excluded.required_certification,number_of_dives=excluded.number_of_dives,price=excluded.price,currency=excluded.currency,featured_image=excluded.featured_image,highlights=excluded.highlights,what_you_learn=excluded.what_you_learn,featured=excluded.featured,sort_order=excluded.sort_order;
insert into public.dive_sites (slug,name,description,long_description,site_type,depth_min,depth_max,difficulty,current_level,marine_life,journey_time,featured_image,gallery,latitude,longitude,featured,sort_order) select x->>'slug',x->>'name',x->>'description',x->>'longDescription',x->>'siteType',(x->>'depthMin')::int,(x->>'depthMax')::int,x->>'difficulty',x->>'currentLevel',array(select jsonb_array_elements_text(x->'marineLife')),x->>'journeyTime',x->>'featuredImage',array(select jsonb_array_elements_text(x->'gallery')),(x->>'latitude')::float8,(x->>'longitude')::float8,(x->>'featured')::boolean,(x->>'_sort')::int from jsonb_array_elements('[{"id":"site-dhangethi-corner","slug":"dhangethi-corner","name":"Dhangethi Corner","description":"A lively reef corner close to home where current brings the reef to life.","longDescription":"Just a short ride from the island, Dhangethi Corner is a rewarding drift along a reef edge where schooling fish, reef sharks and the occasional eagle ray gather in the current. A favourite warm-up dive and a great introduction to South Ari diving.","siteType":"Channel","depthMin":10,"depthMax":30,"difficulty":"Intermediate","currentLevel":"Moderate","marineLife":["Grey reef sharks","Eagle rays","Schooling fusiliers","Napoleon wrasse"],"journeyTime":"approx. 10 min by boat","featuredImage":"/images/site-channel.png","gallery":["/images/site-channel.png","/images/reef-dive.png"],"latitude":3.6,"longitude":72.96,"featured":true,"_sort":0},{"id":"site-emerald-thila","slug":"emerald-thila","name":"Emerald Thila","description":"A coral pinnacle blooming with soft corals and clouds of anthias.","longDescription":"Emerald Thila rises from the sandy bottom in a burst of colour. Its slopes are carpeted in soft corals and swarming with anthias, while the blue around it is patrolled by jacks and the occasional passing pelagic. A photographer’s dream in the right light.","siteType":"Thila","depthMin":12,"depthMax":28,"difficulty":"Intermediate","currentLevel":"Variable","marineLife":["Soft corals","Anthias","Trevally","Moray eels"],"journeyTime":"approx. 25 min by boat","featuredImage":"/images/site-thila.png","gallery":["/images/site-thila.png","/images/reef-dive.png"],"latitude":3.58,"longitude":72.9,"featured":true,"_sort":1},{"id":"site-south-ari-whale-zone","slug":"south-ari-whale-zone","name":"South Ari Whale Shark Zone","description":"The famous stretch of ocean where whale sharks cruise year round.","longDescription":"This protected stretch of South Ari Atoll is one of the few places on earth to see whale sharks throughout the year. Encounters are usually by snorkel near the surface. Sightings are wild and never guaranteed, but few experiences compare to sharing the water with these gentle giants.","siteType":"Whale Shark Area","depthMin":5,"depthMax":20,"difficulty":"All Levels","currentLevel":"Mild","marineLife":["Whale sharks","Turtles","Reef fish"],"journeyTime":"approx. 30–45 min by boat","featuredImage":"/images/whale-shark.png","gallery":["/images/whale-shark.png","/images/whale-shark.png"],"latitude":3.5,"longitude":72.85,"featured":true,"_sort":2},{"id":"site-manta-point","slug":"manta-cleaning-station","name":"Manta Cleaning Station","description":"A reef ridge where mantas glide in to be cleaned by tiny wrasse.","longDescription":"At the right time of year, mantas circle patiently over this reef ridge while cleaner wrasse tend to them. Divers wait quietly below and watch the ballet unfold. Seasonal and weather dependent — our guides read the conditions to give you the best chance.","siteType":"Manta Area","depthMin":8,"depthMax":22,"difficulty":"Beginner","currentLevel":"Mild","marineLife":["Manta rays","Cleaner wrasse","Reef fish","Turtles"],"journeyTime":"approx. 20 min by boat","featuredImage":"/images/manta.png","gallery":["/images/manta.png","/images/reef-dive.png"],"latitude":3.55,"longitude":72.88,"featured":true,"_sort":3},{"id":"site-house-reef","slug":"dhangethi-house-reef","name":"Dhangethi House Reef","description":"Gentle, shallow and endlessly rewarding — perfect for training and easy dives.","longDescription":"The house reef is where many first dives happen. Shallow, sheltered and full of life, it is ideal for training, refreshers and relaxed exploration. Turtles, rays and countless reef fish make even a short dive feel special.","siteType":"Reef","depthMin":3,"depthMax":16,"difficulty":"Beginner","currentLevel":"Mild","marineLife":["Turtles","Rays","Reef fish","Octopus"],"journeyTime":"shore / short boat ride","featuredImage":"/images/reef-dive.png","gallery":["/images/reef-dive.png","/images/dhangethi-aerial.png"],"latitude":3.6,"longitude":72.97,"featured":false,"_sort":4},{"id":"site-blue-channel","slug":"blue-channel","name":"Blue Channel","description":"A dramatic channel dive for experienced divers who love the blue.","longDescription":"Blue Channel is for divers who love current and open water. Drifting into the blue, you may meet grey reef sharks, eagle rays and large schools of fish sweeping through. An exhilarating advanced dive when conditions allow.","siteType":"Channel","depthMin":15,"depthMax":35,"difficulty":"Advanced","currentLevel":"Strong","marineLife":["Grey reef sharks","Eagle rays","Barracuda","Trevally"],"journeyTime":"approx. 35 min by boat","featuredImage":"/images/site-channel.png","gallery":["/images/site-channel.png","/images/reef-dive.png"],"latitude":3.52,"longitude":72.92,"featured":false,"_sort":5}]'::jsonb) x on conflict (slug) do update set name=excluded.name,description=excluded.description,long_description=excluded.long_description,site_type=excluded.site_type,depth_min=excluded.depth_min,depth_max=excluded.depth_max,difficulty=excluded.difficulty,current_level=excluded.current_level,marine_life=excluded.marine_life,journey_time=excluded.journey_time,featured_image=excluded.featured_image,gallery=excluded.gallery,latitude=excluded.latitude,longitude=excluded.longitude,featured=excluded.featured,sort_order=excluded.sort_order;
insert into public.gallery_items (id,title,media_type,image_url,video_url,poster_url,category,caption,featured,sort_order) select (substr(md5(x->>'id'),1,8)||'-'||substr(md5(x->>'id'),9,4)||'-'||substr(md5(x->>'id'),13,4)||'-'||substr(md5(x->>'id'),17,4)||'-'||substr(md5(x->>'id'),21,12))::uuid,x->>'title',(x->>'mediaType')::media_type,x->>'imageUrl',x->>'videoUrl',x->>'posterUrl',x->>'category',x->>'caption',(x->>'featured')::boolean,(x->>'_sort')::int from jsonb_array_elements('[{"id":"g-1","title":"Sunlit reef","mediaType":"image","imageUrl":"/images/reef-dive.png","category":"Underwater","caption":"Morning light over a South Ari reef garden.","featured":true,"_sort":0},{"id":"g-2","title":"Gentle giant","mediaType":"image","imageUrl":"/images/whale-shark.png","category":"Whale Sharks","caption":"A whale shark cruising the South Ari shallows.","featured":true,"_sort":1},{"id":"g-3","title":"Whale shark encounter","mediaType":"video","imageUrl":"/images/whale-shark.png","posterUrl":"/images/whale-shark.png","category":"Whale Sharks","caption":"Video placeholder — client footage to be added.","featured":false,"_sort":2},{"id":"g-4","title":"Manta in flight","mediaType":"image","imageUrl":"/images/manta.png","category":"Mantas","caption":"A manta glides over the cleaning station.","featured":true,"_sort":3},{"id":"g-5","title":"Island lane","mediaType":"image","imageUrl":"/images/dhangethi-aerial.png","category":"Dhangethi","caption":"Quiet palm-lined lanes of Dhangethi.","featured":false,"_sort":4},{"id":"g-6","title":"Beach morning","mediaType":"image","imageUrl":"/images/dhangethi-aerial.png","category":"Dhangethi","caption":"White sand and turquoise lagoon.","featured":true,"_sort":5},{"id":"g-7","title":"Learning to dive","mediaType":"image","imageUrl":"/images/learn-to-dive.png","category":"Guests","caption":"First breaths underwater with our team.","featured":false,"_sort":6},{"id":"g-8","title":"On the dhoni","mediaType":"image","imageUrl":"/images/island-dhoni.png","category":"Boat Life","caption":"Heading out on a traditional dhoni.","featured":false,"_sort":7},{"id":"g-9","title":"Harbour sunset","mediaType":"image","imageUrl":"/images/pkg-escape.png","category":"Island Sunsets","caption":"Golden hour over the Dhangethi harbour.","featured":true,"_sort":8},{"id":"g-10","title":"Channel drift","mediaType":"image","imageUrl":"/images/site-channel.png","category":"Underwater","caption":"Drifting a South Ari channel.","featured":false,"_sort":9},{"id":"g-11","title":"Coral thila","mediaType":"image","imageUrl":"/images/site-thila.png","category":"Underwater","caption":"A pinnacle alive with soft corals.","featured":false,"_sort":10},{"id":"g-12","title":"Island escape","mediaType":"image","imageUrl":"/images/pkg-escape.png","category":"Dhangethi","caption":"Slow island days between dives.","featured":false,"_sort":11}]'::jsonb)x on conflict(id) do update set title=excluded.title,media_type=excluded.media_type,image_url=excluded.image_url,video_url=excluded.video_url,poster_url=excluded.poster_url,category=excluded.category,caption=excluded.caption,featured=excluded.featured,sort_order=excluded.sort_order;
insert into public.testimonials (id,guest_name,country,trip_type,review,guest_image,source,source_url,featured,sort_order) select (substr(md5(x->>'id'),1,8)||'-'||substr(md5(x->>'id'),9,4)||'-'||substr(md5(x->>'id'),13,4)||'-'||substr(md5(x->>'id'),17,4)||'-'||substr(md5(x->>'id'),21,12))::uuid,x->>'guestName',x->>'country',x->>'tripType',x->>'review',x->>'guestImage',x->>'source',x->>'sourceUrl',(x->>'featured')::boolean,(x->>'_sort')::int from jsonb_array_elements('[{"id":"t-1","guestName":"Placeholder Guest","country":"Country","tripType":"Whale Shark Week","review":"This is placeholder testimonial text written to show how a guest review will appear. Real, verified reviews from Fathu Dives guests will replace this content.","guestImage":"/images/guest-avatar.png","source":"Placeholder","_sort":0},{"id":"t-2","guestName":"Placeholder Guest","country":"Country","tripType":"Open Water course","review":"Another placeholder review demonstrating the testimonial layout. The client will provide genuine guest feedback and, where relevant, a source link.","guestImage":"/images/guest-avatar.png","source":"Placeholder","_sort":1},{"id":"t-3","guestName":"Placeholder Guest","country":"Country","tripType":"Dive and Island Escape","review":"Placeholder text only. This section is designed to hold authentic reviews once they are confirmed — no ratings or sources are implied here.","guestImage":"/images/guest-avatar.png","source":"Placeholder","_sort":2}]'::jsonb)x on conflict(id) do update set guest_name=excluded.guest_name,country=excluded.country,trip_type=excluded.trip_type,review=excluded.review,guest_image=excluded.guest_image,source=excluded.source,source_url=excluded.source_url,featured=excluded.featured,sort_order=excluded.sort_order;
insert into public.faqs (id,question,answer,sort_order) select (substr(md5(x->>'id'),1,8)||'-'||substr(md5(x->>'id'),9,4)||'-'||substr(md5(x->>'id'),13,4)||'-'||substr(md5(x->>'id'),17,4)||'-'||substr(md5(x->>'id'),21,12))::uuid,x->>'question',x->>'answer',(x->>'_sort')::int from jsonb_array_elements('[{"id":"faq-1","question":"Do I need previous diving experience?","answer":"Not at all. We welcome complete beginners with introductory experiences and certification courses, as well as certified divers of every level. Let us know your experience when you enquire and we will match you to the right start.","_sort":0},{"id":"faq-2","question":"What is included in a dive package?","answer":"Packages typically include local-island accommodation, breakfast, a set number of guided dives with tanks and weights, and transfer coordination. Exact inclusions are listed on each package page and will be confirmed by the client.","_sort":1},{"id":"faq-3","question":"Is equipment included?","answer":"Tanks and weights are included with guided dives. Full equipment rental (BCD, regulator, wetsuit, mask, fins and computer) can be arranged for an additional fee. Final rental pricing is a placeholder for now.","_sort":2},{"id":"faq-4","question":"How do I reach Dhangethi?","answer":"Dhangethi is reached from Malé by speedboat or the public atoll ferry. We help you choose and coordinate the most suitable transfer based on your flight times.","_sort":3},{"id":"faq-5","question":"Can non-divers join the holiday?","answer":"Absolutely. Dhangethi is a wonderful place to relax, snorkel and explore island life. Non-divers are welcome on many excursions, including whale shark trips.","_sort":4},{"id":"faq-6","question":"What information should certified divers provide?","answer":"Please share your certification level and agency, approximate number of logged dives, and the date of your last dive. This helps us plan suitable sites. Certification details will be verified on arrival.","_sort":5},{"id":"faq-7","question":"Can airport transfers be arranged?","answer":"Yes. We assist with coordinating transfers between Malé and Dhangethi. Share your flight details when enquiring and we will advise on options and timings.","_sort":6},{"id":"faq-8","question":"When is the best time to visit?","answer":"The Maldives is a year-round destination, and South Ari Atoll is known for whale sharks throughout the year. Conditions and marine life vary by season — we are happy to advise based on what you most want to experience.","_sort":7}]'::jsonb)x on conflict(id) do update set question=excluded.question,answer=excluded.answer,sort_order=excluded.sort_order;
insert into public.experiences (id,title,description,level,image,href,size,featured,sort_order) select (substr(md5(x->>'id'),1,8)||'-'||substr(md5(x->>'id'),9,4)||'-'||substr(md5(x->>'id'),13,4)||'-'||substr(md5(x->>'id'),17,4)||'-'||substr(md5(x->>'id'),21,12))::uuid,x->>'title',x->>'description',x->>'level',x->>'image',x->>'href',x->>'size',(x->>'featured')::boolean,(x->>'_sort')::int from jsonb_array_elements('[{"id":"exp-whale-shark","title":"Whale Shark Encounters","description":"Share the water with the ocean’s gentle giants in one of the few places they roam year round.","level":"All levels · snorkel or dive","image":"/images/whale-shark.png","href":"/dive-sites/south-ari-whale-zone","size":"tall","_sort":0},{"id":"exp-manta","title":"Manta Ray Adventures","description":"Hover quietly as mantas glide in to be cleaned — a slow, spellbinding ballet.","level":"Beginner friendly · seasonal","image":"/images/manta.png","href":"/dive-sites/manta-cleaning-station","size":"regular","_sort":1},{"id":"exp-reef","title":"South Ari Reef Diving","description":"Drift channels, coral thilas and living reefs bursting with colour and marine life.","level":"Certified divers","image":"/images/reef-dive.png","href":"/dive-sites","size":"wide","_sort":2},{"id":"exp-learn","title":"Learn to Dive","description":"Take your first underwater breath, guided every moment by a caring professional.","level":"No experience needed","image":"/images/learn-to-dive.png","href":"/dive-courses","size":"regular","_sort":3}]'::jsonb)x on conflict(id) do update set title=excluded.title,description=excluded.description,level=excluded.level,image=excluded.image,href=excluded.href,size=excluded.size,featured=excluded.featured,sort_order=excluded.sort_order;
insert into public.adventure_options (id,label,description,recommendation_type,recommendation_slug,recommendation_label,featured,sort_order) select (substr(md5(x->>'id'),1,8)||'-'||substr(md5(x->>'id'),9,4)||'-'||substr(md5(x->>'id'),13,4)||'-'||substr(md5(x->>'id'),17,4)||'-'||substr(md5(x->>'id'),21,12))::uuid,x->>'label',x->>'description',x->>'recommendationType',x->>'recommendationSlug',x->>'recommendationLabel',(x->>'featured')::boolean,(x->>'_sort')::int from jsonb_array_elements('[{"id":"adv-first-breath","label":"My first underwater breath","description":"Start gently with a guided introduction — no experience required.","recommendationType":"course","recommendationSlug":"discover-scuba-diving","recommendationLabel":"Discover Scuba Diving","_sort":0},{"id":"adv-whale-manta","label":"Whale sharks and mantas","description":"Build your trip around the big encounters South Ari is famous for.","recommendationType":"package","recommendationSlug":"whale-shark-week","recommendationLabel":"Whale Shark Week","_sort":1},{"id":"adv-reefs","label":"Colourful reefs and marine life","description":"Dive as much as you can across the best of South Ari.","recommendationType":"package","recommendationSlug":"south-ari-explorer","recommendationLabel":"South Ari Explorer","_sort":2},{"id":"adv-friends","label":"A diving holiday with friends","description":"A week of diving and island evenings shared with your group.","recommendationType":"package","recommendationSlug":"south-ari-explorer","recommendationLabel":"South Ari Explorer","_sort":3},{"id":"adv-relax","label":"Island relaxation between dives","description":"A balanced blend of easy diving and slow island days.","recommendationType":"package","recommendationSlug":"dive-and-island-escape","recommendationLabel":"Dive and Island Escape","_sort":4},{"id":"adv-photography","label":"Underwater photography","description":"Extend your bottom time and get closer to the reef with enriched air.","recommendationType":"course","recommendationSlug":"enriched-air-nitrox","recommendationLabel":"Enriched Air (Nitrox)","_sort":5}]'::jsonb)x on conflict(id) do update set label=excluded.label,description=excluded.description,recommendation_type=excluded.recommendation_type,recommendation_slug=excluded.recommendation_slug,recommendation_label=excluded.recommendation_label,featured=excluded.featured,sort_order=excluded.sort_order;
insert into public.site_settings(id,contact_email,whatsapp,phone,instagram_url,facebook_url,youtube_url,tripadvisor_url,hero_headline,hero_subheadline,seo_title,seo_description) values(1,'hello@fathudives.com','9600000000','+960 000 0000','https://instagram.com/','https://facebook.com/','https://youtube.com/','https://tripadvisor.com/','Dive the Wild Heart of Dhangethi','Local diving, extraordinary encounters.','Fathu Dives | Dhangethi, Maldives','Scuba diving, courses and island stays in South Ari Atoll.') on conflict(id) do update set contact_email=excluded.contact_email;
